# minimal healthcheck after deploy
curl -sS -o /dev/null -w "%{http_code}" https://your-app.example.com/health  # expect 200

// Node (ESM) sample for sdk8
import Redwood from '@redwood/inference';
if(!process.env.REDWOOD_KEY) throw new Error('set REDWOOD_KEY');
const c = new Redwood({ apiKey: process.env.REDWOOD_KEY });
const r = await c.generate({ model: 'redwood/mini-1', input: 'hello' });
console.log(r.output?.[0]?.text ?? '');
